@Override public void updateItem(final OpenOfferListItem item, boolean empty) {
  super.updateItem(item, empty);
  if (item != null && !empty) {
    if (button == null) {
      button = getIconButton(MaterialDesignIcon.PENCIL);
      setGraphic(button);
    }
    button.setOnAction(event -> {
      try {
        onEditOpenOffer(item.getOpenOffer());
      } catch (IllegalArgumentException e) {
        // Handle or log the exception as appropriate
      }
    });
  } else {
    setGraphic(null);
    if (button != null) {
      button.setOnAction(null);
      button = null;
    }
  }
}
